// Scratch verification prototype (not a deliverable).
const NS: usize = 62;           // NeighborhoodSize
const NRES: u32 = 2;            // reserved bits
const MAXP: usize = 12 * NS;    // MAX_PROBES_FOR_EMPTY_BUCKET = 744
const P63: f32 = 9223372036854775808.0;
const MIN_MLF: f32 = 0.1;
const MAX_MLF: f32 = 0.95;
const MLF_REHASH: f32 = 0.1;
const GP_MAX_BC: usize = 1usize << 63;
const HH_MAX_BC: usize = (usize::MAX / 2) / 16 - (NS - 1); // ptrdiff_max/16 - 61

fn cvttss2si(x: f32) -> i64 {
    if x.is_nan() || x >= P63 || x < -P63 { i64::MIN } else { x as i64 }
}
fn f2sz(x: f32) -> usize {
    if x >= P63 { ((cvttss2si(x - P63) as u64) ^ (1u64 << 63)) as usize }
    else { cvttss2si(x) as u64 as usize }
}
fn u2f(v: usize) -> f32 { v as f32 }
fn rup2(mut v: usize) -> usize {
    if v != 0 && (v & (v - 1)) == 0 { return v; }
    if v == 0 { return 1; }
    v -= 1; let mut i = 1; while i < 64 { v |= v >> i; i *= 2; } v + 1
}

#[derive(Clone, Default)]
struct B { info: u64, kv: (i32, i32) }
impl B {
    fn empty(&self) -> bool { self.info & 1 == 0 }
    fn nb(&self) -> u64 { self.info >> NRES }
    fn has_ovf(&self) -> bool { self.info & 2 != 0 }
    fn set_ovf(&mut self) { self.info |= 2 }
    fn toggle(&mut self, i: usize) { self.info ^= 1u64 << (i as u32 + NRES) }
    fn fill(&mut self, kv: (i32, i32)) { self.info |= 1; self.kv = kv }
    fn clear(&mut self) { self.info &= !1 }
}
struct M { mask: usize, data: Vec<B>, ovf: Vec<(i32,i32)>, n: usize, minth: usize, maxth: usize, mlf: f32 }
fn h(k: i32) -> usize { k as isize as usize }

impl M {
    fn new(mut bc: usize, mlf: f32) -> M {
        assert!(bc <= GP_MAX_BC, "hash table exceeds max");
        let mask = if bc > 0 { bc = rup2(bc); bc - 1 } else { 0 };
        assert!(bc <= HH_MAX_BC, "map exceeds max");
        let data = if bc == 0 { Vec::new() } else { vec![B::default(); bc + NS - 1] };
        let mut m = M { mask, data, ovf: Vec::new(), n: 0, minth: 0, maxth: 0, mlf: 0.0 };
        m.set_mlf(mlf); m
    }
    fn set_mlf(&mut self, ml: f32) {
        self.mlf = if ml > MAX_MLF { MAX_MLF } else if ml > MIN_MLF { ml } else { MIN_MLF };
        let bc = u2f(self.bucket_count());
        self.minth = f2sz(MLF_REHASH * bc);
        self.maxth = f2sz(bc * self.mlf);
    }
    fn bucket_count(&self) -> usize { if self.data.is_empty() { 0 } else { self.data.len() - (NS - 1) } }
    fn next_bc(&self) -> usize { let bc = self.mask + 1; assert!(bc <= GP_MAX_BC / 2); bc * 2 }
    fn bfh(&self, hash: usize) -> usize { hash & self.mask }

    fn find_empty(&self, start: usize) -> usize {
        let limit = std::cmp::min(start.wrapping_add(MAXP), self.data.len());
        let mut i = start;
        while i < limit { if self.data[i].empty() { return i; } i += 1; }
        self.data.len()
    }
    fn swap_closer(&mut self, ie: &mut usize) -> bool {
        if *ie < NS { return false; }
        let start = *ie - NS + 1;
        for tc in start..*ie {
            let mut info = self.data[tc].nb();
            let mut ts = tc;
            while info != 0 && ts < *ie {
                if info & 1 == 1 {
                    let kv = self.data[ts].kv;
                    self.data[ts].clear();
                    self.data[*ie].fill(kv);
                    self.data[tc].toggle(*ie - tc);
                    self.data[tc].toggle(ts - tc);
                    *ie = ts; return true;
                }
                ts += 1; info >>= 1;
            }
        }
        false
    }
    fn will_change(&self, ib: usize) -> bool {
        let ebc = self.next_bc();
        let em = if ebc > 0 { rup2(ebc) - 1 } else { 0 };
        let mut i = ib;
        while i < ib + NS {
            if i >= self.data.len() { return false; }
            let hash = h(self.data[i].kv.0);           // NOTE: no empty check, like tsl
            if (hash & self.mask) != (hash & em) { return true; }
            i += 1;
        }
        false
    }
    fn rehash(&mut self, count: usize) {
        let c = std::cmp::max(count, f2sz((u2f(self.n) / self.mlf).ceil()));
        self.rehash_impl(c);
    }
    fn rehash_impl(&mut self, count: usize) {
        let mut nm = M::new(count, self.mlf);
        if !self.ovf.is_empty() {
            std::mem::swap(&mut nm.ovf, &mut self.ovf);
            nm.n += nm.ovf.len();
            for v in nm.ovf.clone() { let ib = nm.bfh(h(v.0)); nm.data[ib].set_ovf(); }
        }
        for i in 0..self.data.len() {
            if self.data[i].empty() { continue; }
            let kv = self.data[i].kv;
            let hash = h(kv.0);
            nm.insert_value(nm.bfh(hash), hash, kv);
            self.data[i].clear();
            let ib = self.bfh(hash);
            self.data[ib].toggle(i - ib);
            self.n -= 1;
        }
        *self = nm;
    }
    fn insert(&mut self, kv: (i32, i32)) {
        let hash = h(kv.0);
        let ib = self.bfh(hash);
        if !self.data.is_empty() {
            let mut info = self.data[ib].nb();
            let mut j = ib;
            while info != 0 {
                if info & 1 == 1 && self.data[j].kv.0 == kv.0 { return; }
                j += 1; info >>= 1;
            }
            if self.data[ib].has_ovf() && self.ovf.iter().any(|v| v.0 == kv.0) { return; }
        }
        self.insert_value(ib, hash, kv);
    }
    fn insert_value(&mut self, mut ib: usize, hash: usize, kv: (i32, i32)) {
        loop {
            if self.n - self.ovf.len() >= self.maxth {
                let nb = self.next_bc(); self.rehash(nb); ib = self.bfh(hash);
            }
            let mut ie = self.find_empty(ib);
            if ie < self.data.len() {
                loop {
                    if ie - ib < NS {
                        self.data[ie].fill(kv);
                        self.data[ib].toggle(ie - ib);
                        self.n += 1; return;
                    }
                    if !self.swap_closer(&mut ie) { break; }
                }
            }
            if self.n < self.minth || !self.will_change(ib) {
                self.ovf.push(kv); self.data[ib].set_ovf(); self.n += 1; return;
            }
            let nb = self.next_bc(); self.rehash(nb); ib = self.bfh(hash);
        }
    }
    fn reserve(&mut self, c: usize) { let t = f2sz((u2f(c) / self.mlf).ceil()); self.rehash(t) }
}

fn main() {
    let a: Vec<String> = std::env::args().collect();
    let mut count: i32 = 18;
    if a.len() > 2 && a[1] == "--a" { count = a[2].parse().unwrap(); }
    let mut m = M::new(0, 0.9);
    m.reserve(count as isize as usize);
    let mut i = 0i32;
    while i < count { m.insert((i, i.wrapping_mul(14))); i += 1; }
    println!("{} {} {}", m.n, m.bucket_count(), m.ovf.len());
}
EOF
