fn contains(m: &M, k: i32) -> bool {
    if m.data.is_empty() { return false; }
    let ib = m.bfh(h(k));
    let mut info = m.data[ib].nb(); let mut j = ib;
    while info != 0 { if info & 1 == 1 && m.data[j].kv.0 == k { return true; } j += 1; info >>= 1; }
