    false
}
fn check(name: &str, keys: &[i32]) {
    let mut m = M::new(0, 0.9);
    for (i, &k) in keys.iter().enumerate() { m.insert((k, i as i32)); }
    let mut uniq: Vec<i32> = keys.to_vec(); uniq.sort(); uniq.dedup();
    let mut missing = 0;
    for &k in &uniq { if !contains(&m, k) { missing += 1; } }
    // bucket invariant: every occupied bucket is registered in its home bucket bitmap
    let mut badbit = 0; let mut occ = 0;
    for i in 0..m.data.len() {
        if m.data[i].empty() { continue; }
        occ += 1;
        let hb = m.bfh(h(m.data[i].kv.0));
        if i < hb || i - hb >= NS || (m.data[hb].nb() >> (i - hb)) & 1 == 0 { badbit += 1; }
    }
    println!("{:<26} n={:<7} uniq={:<7} bc={:<9} ovf={:<7} missing={} badbit={} occ+ovf={}",
        name, m.n, uniq.len(), m.bucket_count(), m.ovf.len(), missing, badbit, occ + m.ovf.len());
    assert!(missing == 0 && badbit == 0 && occ + m.ovf.len() == m.n, "INVARIANT FAIL {}", name);
}
fn main() {
    check("seq 0..1000", &(0..1000).collect::<Vec<i32>>());
    check("all-collide <<20 x2048", &(0..2048).map(|i| i << 20).collect::<Vec<i32>>());
    check("all-collide <<20 x64", &(0..64).map(|i| i << 20).collect::<Vec<i32>>());
    check("all-collide <<20 x63", &(0..63).map(|i| i << 20).collect::<Vec<i32>>());
    check("all-collide <<20 x62", &(0..62).map(|i| i << 20).collect::<Vec<i32>>());
    check("mult of 64 x5000", &(0..5000).map(|i| i * 64).collect::<Vec<i32>>());
    check("mult of 1024 x5000", &(0..5000).map(|i| i * 1024).collect::<Vec<i32>>());
    check("dups", &(0..2000).map(|i| i % 100).collect::<Vec<i32>>());
    check("negatives", &(-2000..0).collect::<Vec<i32>>());
    check("mixed sign step 65536", &(-500..500).map(|i| i * 65536).collect::<Vec<i32>>());
    // pseudo-random
    let mut s: u64 = 0x243F6A8885A308D3;
    let mut v = Vec::new();
    for _ in 0..20000 { s ^= s << 13; s ^= s >> 7; s ^= s << 17; v.push((s >> 33) as i32); }
    check("xorshift 20000", &v);
    // clustered: many keys sharing low bits, high bits differ (should trigger grow-and-retry)
    check("i*4096 x300", &(0..300).map(|i| i * 4096).collect::<Vec<i32>>());
    check("i*2^28 x300", &(0..300).map(|i| i.wrapping_mul(1<<28)).collect::<Vec<i32>>());
}
'''
